opts={'A':'Z ? B x T & J ! L','B':'Z ? B ! T & J x L','C':'Z ! B x T ? J & L','D':'Z & B ! T x J ? L'}
rel={'?':'mother','!':'wife','&':'brother','x':'father'}
def fits(s):
    t=s.split(); names=t[0::2]; ops=[rel[o] for o in t[1::2]]
    # need Z mother of P, P father of (Q or Q's sibling), wife of L
    if ops[0]!='mother' or ops[1]!='father' or ops[-1]!='wife': return False
    return all(o in('brother',) for o in ops[2:-1])
ok=[k for k,v in opts.items() if fits(v)]
assert ok==['A']

